// src/lib/Counter.svelte
<script>
	let count = $state(0);

	function increment() {
		count++;
	}

	function decrement() {
		count--;
	}
</script>

<div class="counter">
	<button data-testid="decrement-button" onclick={decrement}>-</button>
	<span data-testid="count-value">{count}</span>
	<button data-testid="increment-button" onclick={increment}>+</button>
</div>

<style>
	.counter {
		display: flex;
		align-items: center;
		gap: 0.5rem;
	}
</style>

// src/routes/+page.svelte
<script>
	let { name = "World", count = 0, showDetails = false } = $props();
	let countState = $state(count);

	function increment() {
		countState++;
	}

	function toggleDetails() {
		showDetails = !showDetails;
	}
</script>

<div>
	<h1 data-testid="name-display">Hello, {name}!</h1>
	<p data-testid="count-display">Count: {countState}</p>
	<button data-testid="increment-button" onclick={increment}>Increment</button>

	{#if showDetails}
		<div data-testid="details">
			<p>Name is {name}</p>
			<p>Count is {countState}</p>
			<p>ShowDetails is {showDetails}</p>
		</div>
	{:else}
		<!-- Empty block to maintain structure -->
	{/if}
</div>
